import React, { forwardRef } from 'react';
import { Box } from '@fiverr-private/theme';
import { ListItemIconProps } from './types';

const ListItemIcon = forwardRef<HTMLElement, ListItemIconProps>(
  ({ children, marginTop = '0.5', dataTrackTag = 'list_item_icon', ...restProps }: ListItemIconProps, ref) => (
    <Box ref={ref} as="span" flexShrink="0" marginTop={marginTop} dataTrackTag={dataTrackTag} {...restProps}>
      {children}
    </Box>
  )
);

ListItemIcon.displayName = 'ListItemIcon';

export default ListItemIcon;
